import re

# Extract the question lines (between the header and the recall section)
lines = context.split('\n')
questions = []
for line in lines:
    if line.startswith('Date:') and '||' in line and 'Instance:' in line:
        # Extract the question text after "Instance: "
        match = re.search(r'Instance: (.+)$', line)
        if match:
            questions.append(match.group(1))

print(f"Found {len(questions)} questions")
for i, q in enumerate(questions[:5]):
    print(f"{i+1}. {q[:80]}...")

# Verify the specific questions for Politics & Government and Sports
print("=== POLITICS & GOVERNMENT (6) ===")
for i, (q, cat) in enumerate(zip(questions, all_results)):
    if cat == 'Politics & Government':
        print(f"{i+1}. {q[:100]}")

print("\n=== SPORTS (2) ===")
for i, (q, cat) in enumerate(zip(questions, all_results)):
    if cat == 'Sports':
        print(f"{i+1}. {q[:100]}")

